import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';import '../controllers/citas_controller.dart';import '../widgets/cita_form.dart';import '../widgets/cita_table.dart';import '../widgets/cita_actions.dart';class CitasScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const CitasScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<CitasScreen> createState() => _CitasScreenState();}class _CitasScreenState extends State<CitasScreen> {  final _controller = CitasController();  @override  void initState() {    super.initState();    _controller.addListener(() => setState(() {}));    _controller.cargarCitas();  }  @override  void dispose() {    _controller.dispose();    super.dispose();  }  void _abrirFormulario({dynamic existente}) {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => CitaForm(        existente: existente,        onSubmit: (cita) async {          if (existente != null) {            await _controller.actualizarCita(cita);          } else {            await _controller.crearCita(cita);          }          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              SnackBar(content: Text(existente != null ? 'Cita actualizada' : 'Cita creada')),            );          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Citas',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildFiltros() {    return Wrap(      spacing: 8,      runSpacing: 8,      children: [        _buildFiltroChip('Todas', 'todas'),        _buildFiltroChip('Pendientes', 'pendiente'),        _buildFiltroChip('Confirmadas', 'confirmada'),        _buildFiltroChip('Completadas', 'completada'),        _buildFiltroChip('Canceladas', 'cancelada'),      ],    );  }  Widget _buildFiltroChip(String label, String valor) {    final isSelected = _controller.filtroEstado == valor;    return FilterChip(      label: Text(label),      selected: isSelected,      onSelected: (_) => _controller.setFiltroEstado(valor),      selectedColor: AppColors.brandGreen,      checkmarkColor: Colors.white,      labelStyle: TextStyle(        color: isSelected ? Colors.white : AppColors.textSecondary,        fontWeight: isSelected ? FontWeight.w600 : FontWeight.normal,      ),    );  }  Widget _buildContent() {    if (_controller.isLoading) {      return const Center(child: CircularProgressIndicator());    }    if (_controller.error != null) {      return Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            const Icon(Icons.error_outline, size: 48, color: AppColors.negativeRed),            const SizedBox(height: 16),            Text('Error: ${_controller.error}', style: const TextStyle(color: AppColors.textPrimary)),            const SizedBox(height: 16),            ElevatedButton(              onPressed: _controller.cargarCitas,              child: const Text('Reintentar'),              ),          ],        ),      );    }    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        PageHeader(          title: 'Gestión de Citas',          count: _controller.citas.length,          buttonLabel: 'Nueva Cita',          onButtonPressed: () => _abrirFormulario(),        ),        const SizedBox(height: 16),        _buildFiltros(),        const SizedBox(height: 16),        if (_controller.citasFiltradas.isEmpty)          Container(            padding: const EdgeInsets.all(40),            decoration: BoxDecoration(              color: AppColors.cardBg,              borderRadius: BorderRadius.circular(16),              border: Border.all(color: AppColors.cardBorder),            ),            child: const Center(              child: Text('No hay citas registradas', style: TextStyle(color: AppColors.textSecondary)),            ),          )        else          CitaTable(              citas: _controller.citasFiltradas,              onEdit: (c) => _abrirFormulario(existente: c),              onDelete: (c) => CitaActions.confirmarEliminar(context, c, () async {                try {                  await _controller.eliminarCita(c.id);                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Cita eliminada')));                  }                } catch (e) {                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.negativeRed),                    );                  }                }              }),            ),      ],    );  }}